//! Official Core and independent Python/OpenSSL vectors, no chain verdict.
use tradelayer_core::litecoin_scrypt::{
    litecoin_header_id, litecoin_scrypt_pow_hash, LitecoinScrypt, LITECOIN_HEADER_BYTES,
    LITECOIN_SCRYPT_ROMIX_BYTES,
};
fn header(text: &str) -> [u8; 80] {
    assert_eq!(text.len(), 160);
    std::array::from_fn(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).unwrap())
}
fn display(raw: [u8; 32]) -> String {
    raw.iter().rev().map(|byte| format!("{byte:02x}")).collect()
}
