#[test]
fn all_five_official_core_scrypt_known_answers() {
    let mut workspace = LitecoinScrypt::new();
    for &(raw, wanted) in CORE {
        let header = header(raw);
        assert_eq!(display(litecoin_scrypt_pow_hash(&header)), wanted);
        assert_eq!(display(workspace.hash(&header)), wanted);
    }
}
#[test]
fn all_three_genesis_identifiers_and_separate_pow_digests() {
    let mut workspace = LitecoinScrypt::default();
    for &(raw, identifier, pow) in GENESIS {
        let header = header(raw);
        let id = litecoin_header_id(&header);
        let work = workspace.hash(&header);
        assert_eq!(display(id), identifier);
        assert_eq!(display(work), pow);
        assert_ne!(id, work, "RPC identifier and separate Scrypt work digest");
        let expected_raw: Vec<_> = (0..32)
            .map(|i| u8::from_str_radix(&pow[2 * i..2 * i + 2], 16).unwrap())
            .rev()
            .collect();
        assert_eq!(
            work.as_slice(),
            expected_raw,
            "API returns raw digest, not display bytes"
        );
    }
}
#[test]
fn openssl_cross_checks_and_reuse_order_independence() {
    let mut workspace = LitecoinScrypt::new();
    for &(raw, wanted) in OPENSSL.iter().chain(OPENSSL.iter().rev()).chain(CORE) {
        assert_eq!(display(workspace.hash(&header(raw))), wanted);
    }
    assert_eq!(LITECOIN_HEADER_BYTES, 80);
    assert_eq!(LITECOIN_SCRYPT_ROMIX_BYTES, 128 * 1024);
}
#[test]
fn independent_workspaces_are_thread_safe_without_shared_state() {
    std::thread::scope(|scope| {
        for &(raw, wanted) in CORE {
            scope
                .spawn(move || assert_eq!(display(litecoin_scrypt_pow_hash(&header(raw))), wanted));
        }
    });
}
